from apply import apply
E = [
(1, 'Он носил её с собой дольше, чем я — некоторые хорошие намерения.',
    'Судя по сгибу, носил он её все двенадцать лет.', 'ENS-020 натянутая шутка'),
(1, 'Прежде я бы назвал всё законченным уже за рамкой; теперь Дживс спрашивал адрес всякий раз, когда я говорил «довёз» раньше времени.',
    'Я сказал «довёз». Дживс спросил адрес приёмки. Я поправился: «везу».', 'ENS-011 рост показан действием'),
(2, 'Веда записала потерю времени в маршрут, рядом с остатком до церемонии. От этой записи наш выбор не стал ни величественнее, ни дешевле.',
    'Веда вписала семь часов в маршрут — мелко, в графу потерь, рядом с остатком до церемонии.', 'ENS-011 тик'),
(3, 'Это было правильно решено, проговорено и подтверждено всеми, кому полагалось. Оттого пустое место под динамиком не стало приятнее.',
    'Всё было правильно решено, проговорено и подтверждено всеми, кому полагалось. Под динамиком, где Тимка обычно возился с деталями, лежала одна забытая шайба.', 'ENS-011 тик → предмет'),
(6, 'Я бы предпочёл одну дерзкую стрелку через всю карту, но две взрослые женщины на корабле почему-то не собирались позволять мне красивый почерк за общий счёт.',
    'Я бы предпочёл одну дерзкую стрелку через всю карту. Карта предпочитала три столбца недостающего.', 'ENS-020 неловкая фраза'),
(8, '— Пять у вас доказаны. Ещё по части совпадают поставки. Остальное пока дыры, не кладбища. Я не продам вам готовую карту всей катастрофы. У меня её нет.',
    '— Пять у вас доказаны. По остальным совпадают поставки, и, между нами, там везде одно и то же. Можете смело считать кладбищами.\n\n— Не можем, — сказала Веда. — Основание по каждому.\n\nДрозд вздохнул так, будто у него отобрали половину выручки.\n\n— Дыры, — поправился он. — Пока дыры. Готовой карты всей катастрофы у меня нет. Была бы — продал.', 'ENS-009 торговец завышает, Веда ловит'),
(8, 'Мы уже взяли. От совпадения двух чужих предусмотрительностей не стало спокойнее.',
    'Мы уже взяли. Джулия выбрала самые узкие.', 'ENS-011 тик'),
(9, 'Ниже — проверить, что можно сделать с источником и согласятся ли они. От такой расстановки весь риск не исчезал; зато два человека переставали выглядеть принадлежностями единственного большого намерения.',
    'Ниже, мельче — источник. И то если они согласятся.', 'ENS-011 объяснение после бита'),
(11, 'Смотрительница попросила снять кольца. Колец у меня не было. Она всё равно проверила пальцы и выдала сухую салфетку.',
    'Смотрительница попросила меня снять кольца. Я их никогда не носила: на причале у меня тоже ничего не было на руках, и с тех пор пальцы привыкли оставаться пустыми. Она всё равно проверила их и выдала сухую салфетку.', 'ENS-010 признак рассказчицы в первой строке'),
(11, 'Значит, живое распознавание и движение действительно были разными частями. Правильно сказанное слово в реестре не распахивало камень само по себе. Нужны были энергия, исправное соединение и разрешённый режим.',
    'Значит, рука и движение — разные вещи. Камень узнал меня, а шевелиться без питания не стал.', 'ENS-010 голос Джулии'),
(11, 'Я посмотрела на указатель к столовой, где вчера мы ели сладкий хлеб с супом.',
    'Я посмотрела на указатель к столовой, где вчера Кай макал свою сладкую корку в суп и признал, что я права.', 'ENS-019 хлеб'),
(11, 'Ни слабее, ни достойнее тех, кто остался на причале, я за эту проверку не стала. Зато теперь у меня был ответ конкретного устройства и вопрос к конкретному мастеру. С таким грузом я умела идти сама.',
    'Семьдесят человек остались на причале так же, как утром. У меня в кармане лежал лист с ответом одной старой панели и имя мастера, которого можно спросить. С таким грузом я умела идти сама.', 'ENS-010/011 голос, тик'),
(12, 'Кай с инструментом её частью от этого не становился.',
    'Меня с инструментом в эту бригаду никто бы не записал.', 'ENS-019 сбой POV'),
(12, 'Я не собирался спорить. После Велда хорошая схема без сведений о тех, кто под ней живёт, уже не выглядела для меня полной. Но новая возможность всё равно щекотала неприятно: сеть могла усердно исполнить неправильно заданную работу. Человек, задавший её, не получал от этого права говорить, что сам ничего не сломал.',
    'Я не собирался спорить. Новая возможность щекотала неприятно: сеть могла усердно исполнить неправильно заданную работу, а человек, задавший её, потом говорил бы, что сам ничего не ломал. Я знал этот голос. Иногда он звучал моим.', 'ENS-011 прямая формула роста'),
(13, 'Оставшееся утро ушло на допуск корабля. Я хотел держать «Милю» ближе к наземному выходу, а городской порт предлагал платное размещение на дальней площадке. Стоимость не была главной неприятностью. С дальней площадки рампа выходила в закрытую зону, где нельзя было принимать людей без зарегистрированного перехода.\n\nМы перебрали условия, нашли место рядом с ремонтным рукавом и оставили заявку. Там тоже проверяли, что за оборудование я собирался привезти. Пришлось приложить настоящий обменник и согласие подрядчика; тот взял ещё одну небольшую плату за перевозку своего тяжёлого хлама моим кораблём. Я начинал понимать, почему в Кенари любят последовательные процедуры. На каждой можно было честно заработать.',
    'Оставшееся утро ушло на стоянку. С дальней площадки рампа выходила в закрытую зону, где нельзя принимать людей, поэтому я выпросил место у ремонтного рукава, приложив к заявке настоящий обменник подрядчика. Подрядчик взял с меня ещё и за перевозку своего хлама моим кораблём. В Кенари любили последовательные процедуры: на каждой можно было честно заработать.', 'ENS-001 сжатие формальностей'),
(13, 'Я подписал. Отказ от лёгкого места не превращал нашу настоящую цель в законную. Он только оставлял Нерану его комнату. Небольшой результат, если мерить Холмом Розмари. Достаточный, если вечером возвращаться с двумя чашками именно туда.',
    'Я подписал. Через неделю Неран вернётся с двумя чашками в свою комнату. Больше гордиться в этом листе мне было нечем.', 'ENS-001/011 вывод после поступка'),
(14, 'На последнем повороте подлётного коридора «Миля» встала носом к городу.',
    'До церемонии оставалось восемь суток. На последнем повороте подлётного коридора «Миля» встала носом к городу.', 'ENS-001 счётчик суток'),
(14, 'Нас поставили в ожидание между молочным танкером и пассажирским челноком. На челноке ребёнок прижимал ладони к круглому окну. Я подумал, что Тимка уже придумал бы танкеру имя. Потом проверил входящие: последнее сообщение с тихого мира было принято, нового не было. Там сейчас тоже приближался вечер.\n\nОсмотрщик попросил показать номер обменника. Я включил камеру в грузовом отсеке. Номер лежал под обвязкой.\n\n— Снимите ленту.\n\n— В полёте крепление не трогаю.\n\n— Без чтения номера посадка не подтверждается.\n\nМы помолчали, каждый при своём правильном требовании.\n\n— В договоре есть фотография перед погрузкой, — сказал я. — И пломба на внешнем кольце. Её видно. Сверьте пломбу, посадите в досмотровое место, там сниму.\n\nОсмотрщик изучал предложение почти минуту. За это время молочный танкер ушёл вниз, и я успел пожалеть, что не выбрал более текучую профессию. Наконец под нами загорелся разрешённый коридор. Вместо ремонтного рукава он вёл на отдельную площадку с жёлтыми краями.',
    'Нас поставили в ожидание между молочным танкером и пассажирским челноком. На челноке ребёнок прижимал ладони к круглому окну. Тимка уже придумал бы танкеру имя.\n\nОсмотрщик хотел прочесть номер обменника, который лежал под обвязкой. Я отказался трогать крепление в полёте и предложил сверить пломбу. Мы помолчали, каждый при своём правильном требовании. Молочный танкер успел уйти вниз, и я пожалел, что не выбрал более текучую профессию. Наконец загорелся коридор — не к ремонтному рукаву, а на досмотровую площадку с жёлтыми краями.', 'ENS-002 сжатие досмотра'),
(14, 'У ремонтного рукава нас ждал приёмщик подрядчика. Перед собой он держал тележку, явно слишком короткую для обменника. Мы вместе измерили раму. Потом ещё раз, потому что приёмщик надеялся, что со второго раза железо станет сговорчивее.\n\n— В заявке длина без фланцев, — сказал он наконец.\n\n— В моей с фланцами.\n\n— У меня без.\n\nЯ уже знал город достаточно, чтобы не предлагать просто записать другое число. Пришлось запросить другую тележку. Пока она ехала, мы пили воду из его термоса и держали обменник там, где он никому не перекрывал проход. Каждые полминуты над нами проходила тихая грузовая платформа. Одна везла ящики с рассадой, другая — одинаковые синие кресла. На третьей сидел человек и придерживал ногой коробку с тортом.\n\nГород жил не церемонией. До церемонии оставалось несколько дней; до конца смены приёмщика — сорок минут. Второе занимало его гораздо сильнее.',
    'У ремонтного рукава приёмщик подрядчика привёз тележку, явно слишком короткую для обменника: в его заявке длина стояла без фланцев. Я уже знал город достаточно, чтобы не предлагать записать другое число. Пока ехала вторая тележка, мы пили воду из его термоса. Над нами проходили тихие грузовые платформы: ящики с рассадой, одинаковые синие кресла, человек, придерживающий ногой коробку с тортом.\n\nГород жил не церемонией. До церемонии оставалось восемь суток, до конца смены приёмщика — сорок минут. Второе занимало его гораздо сильнее.', 'ENS-002 сжатие'),
(16, '— Смотрительница про тебя спрашивала.', '— Распорядительница про тебя спрашивала.', 'ENS-019 термин'),
(17, '— Смотрительница, — сообщил Дживс.', '— Распорядительница Ясна, — сообщил Дживс.', 'ENS-019 термин'),
(17, '— На прочих надзорных людей твоей жизни она, кажется, плохо похожа.', '— Не похожа она на твоих прежних надзирателей.', 'ENS-020 корявая реплика'),
]
apply(E)
